(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["de"] = {"ui":{"skip":"Zum Inhalt springen","back":"← Zurück zu AI-gile","lang.button":"Sprache: {name}","lang.dialog":"Sprache wählen","lang.search":"Sprachen suchen","lang.none":"Keine Sprache gefunden","lang.notYet":"{name} ist noch nicht übersetzt","theme.aria":"Zwischen hellem und dunklem Design wechseln","theme.toLight":"Zum hellen Design wechseln","theme.toDark":"Zum dunklen Design wechseln","index.title":"AI-gile: dein KI-Entwicklerteam auf einem Board","index.description":"AI-gile ist ein Kanban-Board für KI-Coding-Teams. Sie arbeiten, während du schläfst; du bekommst einen kurzen Stapel zum Entscheiden, Testen und Abnehmen.","hero.logoAlt":"AI-gile-Board-Symbol","hero.h1.html":"Dein KI-Entwicklerteam auf einem&nbsp;Board.","hero.alpha":"🐣 Geschlossene Pre-Alpha","hero.alphaTitle":"Früh und unfertig: danke fürs Ausprobieren!","hero.lede":"Sie bauen, während du schläfst. Du wachst auf und findest einen kurzen Stapel: ein paar Fragen, ein paar Dinge zum Testen, ein oder zwei lila Rauten. Klicken, abnehmen, zurück zum Kaffee.","dl.windows":"Windows-App","dl.browser":"Im Browser starten","dl.soon":"Bald verfügbar","dl.notify":"🔔 Sag mir Bescheid, wenn es losgeht","dl.notifySmall":"Alpha oder Beta","hero.secondary":"Agil, aber das Team braucht nie einen Stand-up-Kaffee. (Stand-ups machen sie trotzdem.)","pitch.h2":"AI-gile in so vielen Wörtern, wie du magst","pitch.lede":"Wähle eine Länge, von einem Wort bis 144. Jede Länge ist eine eigene Beschreibung, geschrieben für genau diese Größe. Zieh den Regler oder nimm die Pfeiltasten.","pitch.rangeLabel":"Länge in Wörtern","pitch.dice":"🎲 noch eine Version","pitch.words.one":"{n} Wort","pitch.words.other":"{n} Wörter","pitch.letters.one":"{n} Buchstabe","pitch.letters.other":"{n} Buchstaben","pitch.chars.one":"{n} Zeichen","pitch.chars.other":"{n} Zeichen","count.line.html.one":"{n} Karte gerade auf dem Board","count.line.html.other":"{n} Karten gerade auf dem Board","features.aria":"Was es kann","f.pile.h":"Ein Stapel für dich","f.pile.html":"<b>Für dich</b> sammelt alles, was auf dich wartet, über alle Projekte hinweg: Fragen, Dinge zum Testen, Aufgaben, die nur ein Mensch erledigen kann. Deine Warteschlange sagt, was als Nächstes dran ist und wie lange es dauert.","f.sleep.h":"Teams, die arbeiten, während du schläfst","f.sleep.p":"Jedes Projekt hat einen Lead und ein Team aus KI-Agenten. Kommentiere eine Karte, und das Team wacht auf, erledigt die Arbeit und gibt sie zurück, mit Schritten, die auch ein müder Mensch versteht.","f.tester.h":"Zuerst prüft ein KI-Tester","f.tester.p":"Bevor etwas bei dir landet, folgt ein Tester den Schritten in einer Kopie der App und zeigt mit einem Screenshot, was er gesehen hat. Blättere durch die bestandenen und nimm sie mit einem Klick ab.","f.proof.h":"Belege statt Versprechen","f.proof.p":"Jede Übergabe zeigt, was sich geändert hat: die Dateien, den Diff, die Screenshots. Du musst nicht jede App öffnen, um zu sehen, ob es fertig ist.","f.chat.h":"Chatte mit deinen Leads","f.chat.p":"Eine Leiste wie bei Discord: ein Symbol pro Projekt, lila Rauten für alles, was dich braucht. Schreib einem Lead eine Idee; er macht daraus Karten und einen Plan, mit einem ✅ Los-Knopf.","f.tidy.h":"Hält sich selbst in Ordnung","f.tidy.p":"Verwandte Karten werden zu einer, wirre Titel werden repariert, und ein Token-Check hält den Code schlank. Weniger, zwischen dem du wechseln musst, weniger zum Nachdenken.","f.private.h":"Deins, auf deinem Computer","f.private.li1":"Das Board läuft auf deinem eigenen Rechner und antwortet nur dir.","f.private.li2":"Private Nachrichten zwischen Menschen sind Ende-zu-Ende-verschlüsselt.","f.private.li3":"Keine Konten, keine Tracker, keine Cookies.","f.lang.h":"In deiner Sprache","f.lang.p":"Über 120 Sprachen, von Niederländisch, Walisisch und Japanisch bis Piratisch, Yoda und Klingonisch, mit einem schnellen Wechsel zurück zu Englisch für die Entwicklerwörter.","tl.aria":"Zeitleiste vom ersten Gespräch bis zur Roadmap","tl.h2":"Vom ersten Chat bis zu dem, was kommt","tl.lede":"Echte Daten und Uhrzeiten, in deiner eigenen Zeitzone. Nach heute ist es der Plan, ohne versprochene Termine.","tl.today":"Heute","tl.planned":"geplant","tl.cards.one":"{n} Karte","tl.cards.other":"{n} Karten","join.h2":"Mach mit","join.lede":"AI-gile wird von einem kleinen Menschen und sehr vielen geduldigen Agenten gebaut. Vorerst ist es privat, in einer geschlossenen Alpha mit Freunden. Lust auf einen Versuch, wenn es sich öffnet?","join.btn":"Interesse anmelden","join.small":"Wir mailen dir, sonst nichts","footer.tag":"AI-gile. Keine Tracker, keine Cookies, kein Stand-up-Kaffee.","footer.licence":"Geschäftslizenz","footer.status":"Status","form.sending":"Wird gesendet…","form.failed":"Das hat nicht geklappt: versuch es später noch einmal.","form.offline":"AI-gile ist nicht erreichbar: versuch es später noch einmal.","interest.title":"AI-gile: sag mir Bescheid, wenn die Alpha startet","interest.description":"Hinterlasse deine E-Mail-Adresse, um zu erfahren, wann die geschlossene Alpha oder Beta von AI-gile startet.","interest.h1":"🔔 Sag mir Bescheid, wenn es losgeht","interest.lede":"AI-gile ist in der geschlossenen Pre-Alpha. Hinterlasse deine E-Mail-Adresse, und wir schreiben dir einmal, wenn ein Platz für dich frei ist.","interest.email":"Deine E-Mail","interest.which":"Welcher Test?","interest.alpha":"Geschlossene Alpha: früh, rau, viele Änderungen","interest.beta":"Beta: stabiler, später","interest.both":"Egal, was zuerst kommt","interest.submit":"Trag mich in die Liste ein","interest.thanks":"Danke! Du stehst auf der Liste.","interest.kept":"Gespeichert werden nur deine E-Mail-Adresse und der gewählte Test, nur für diese Liste. Kein Newsletter, keine Tracker.","licence.title":"AI-gile: Geschäftslizenz","licence.description":"Du nutzt AI-gile in deinem Unternehmen? Beantrage eine kostenlose Geschäftslizenz.","licence.h1":"📜 Geschäftslizenz","licence.lede":"Du nutzt AI-gile bei der Arbeit? Erzähl uns, wer du bist und was du machst. Wenn es etwas Gutes bewirkt, ist die Lizenz kostenlos.","licence.company":"Unternehmen","licence.website":"Website","licence.what":"Was du machst","licence.how":"Wie es der Welt hilft","licence.email":"E-Mail","licence.submit":"Beantragen","licence.thanks":"Danke! Wir antworten per E-Mail.","status.title":"AI-gile-Status","status.h1":"AI-gile-Status","status.quiet":"Alles ruhig","status.checking":"Wird geprüft…","status.offline":"Der Status-Dienst ist gerade nicht erreichbar (neuer Versuch folgt)","status.updated":"aktualisiert {ago}","status.justNow":"gerade eben","status.min":"vor {n} Min.","status.hours":"vor {n} Std.","status.days":"vor {n} T.","live.h2":"Live zuschauen, wie es gebaut wird","live.caption":"Jede Karte ist verborgen: Du siehst die Form der Arbeit, nicht die Worte.","live.watching.one":"live: {n} schaut zu","live.watching.other":"live: {n} schauen zu","live.offline":"Das Live-Board macht kurz Pause. Schau bald wieder vorbei.","live.cols":"Backlog|Zu tun|In Arbeit|Team prüft|Zum Testen für dich|Fürs Team|Erledigt","live.last.now":"Letzte Karte gerade eben verschoben","live.last.min.one":"Letzte Karte vor {n} Min. verschoben","live.last.min.other":"Letzte Karte vor {n} Min. verschoben","live.last.hour.one":"Letzte Karte vor {n} Stunde verschoben","live.last.hour.other":"Letzte Karte vor {n} Stunden verschoben","live.last.day.one":"Letzte Karte vor {n} Tag verschoben","live.last.day.other":"Letzte Karte vor {n} Tagen verschoben"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboter.","Delegiert."]},{"n":2,"texts":["Kanban, automatisiert.","Agenten, geordnet.","Ideen, gebaut."]},{"n":3,"texts":["Kanban für Roboter.","Ideen werden Features.","Kostenloses Kanban, lokal."]},{"n":5,"texts":["Ein Kanban-Board, das Agenten abarbeiten.","Du schreibst Karten. Agenten bauen.","Kostenlos, lokal, getestet, leicht albern."]},{"n":8,"texts":["Ein kostenloses Kanban-Board, auf dem KI-Agenten richtig arbeiten.","Schreib eine Idee. Agenten bauen sie. Du nimmst ab.","Agil für einen Menschen und viele geduldige Roboter."]},{"n":13,"texts":["Ein Kanban-Board auf deinem Computer, bei dem KI-Agenten die Karten übernehmen und abarbeiten.","Schreib eine Idee. Ein Agententeam baut sie. Ein Tester prüft sie. Du sagst Ja.","Kostenlos, ohne Konten, ohne Tracker: ein Board, ein paar Roboter, und du hast das Sagen."]},{"n":21,"texts":["AI-gile ist ein Kanban-Board für die Arbeit mit KI-Coding-Agenten. Sie übernehmen die Karten; du testest sie und nimmst sie ab.","Jedes Projekt bekommt einen Lead und ein Team aus KI-Agenten. Kommentiere irgendeine Karte, und schon legt das Team los.","Ein kostenloses, persönliches To-do-Board, das auf deinem eigenen Computer läuft. Die Arbeiter sind Roboter. Wer Ja sagt, bist du."]},{"n":34,"texts":["Du legst Ideen auf ein Board. Ein Team aus KI-Agenten macht daraus funktionierende Features, testet sie und gibt sie dir zurück, samt Schritten zum Ausprobieren. Erledigt ist erst, was du als erledigt erklärst.","AI-gile ist ein selbstgebautes Kanban-Board. Rich hat es mit viel Hilfe genau der Agenten gebaut, die es heute verwaltet. Es ist kostenlos, läuft auf deinem Computer und wird mit Freunden geteilt, nicht verkauft.","Stell dir ein ganz normales Kanban-Board vor, mit Spalten von Backlog bis Erledigt, nur dass die Karten von KI-Agenten bearbeitet werden. Sie melden den Fortschritt, fragen nach, wenn sie hängen, und warten immer auf dein Okay."]},{"n":55,"texts":["AI-gile ist ein Kanban-Board, dessen Team aus KI-Agenten besteht. Jedes Projekt hat einen Lead, der die Arbeit plant, und Helfer, die sie bauen. Ist ein Feature fertig, probiert ein KI-Tester es aus und macht einen Screenshot, dann landet es auf deinem Stapel. Nimm es ab, oder kommentiere, und sie überarbeiten es.","Es fing als Weg eines einzelnen Menschen an, den Überblick über viele KI-Coding-Sitzungen gleichzeitig zu behalten, und wuchs zu einem richtigen Board heran. Es läuft auf deinem Rechner, braucht kein Konto und hat keine Tracker. Für Freunde und Neugierige ist es kostenlos. Es ist auch unfertig, also rechne mit Ecken, Kanten und der einen oder anderen Überraschung.","Hier die ehrliche Version. Die Ideen musst du immer noch selbst haben, und die Ergebnisse musst du immer noch selbst prüfen. Alles dazwischen übernimmt AI-gile: Es hält die Karten in Ordnung, weckt den richtigen Agenten, wenn du kommentierst, zeigt genau, was sich geändert hat, und legt alles auf einen kurzen Stapel für dich."]},{"n":89,"texts":["AI-gile ist ein kostenloses Kanban-Board, das du auf deinem eigenen Computer laufen lässt. Statt Menschen hat jedes Projekt ein Team aus KI-Agenten: einen Lead, der deine Ideen in Karten und einen Plan verwandelt, und Helfer, die die Karten der Priorität nach abarbeiten. Ist etwas gebaut, folgt ein KI-Tester den Testschritten und zeigt dir, was er gesehen hat. Dann wartet es auf einem Stapel mit dem Namen Für dich. Du nimmst es ab, oder du kommentierst und das Team versucht es noch einmal. Nichts landet je ohne dich bei Erledigt.","Ein paar Dinge, die du vielleicht nicht erwartest. Eine Nachtwache hält die Spalte Zu tun gefüllt, während du schläfst, und wählt Karten, für die sie keine Antwort von dir braucht. Ein Token-Zähler zeigt, wie viel die Agenten heute und diese Woche verbraucht haben, und der Kein-Token-Modus sagt ihnen, dass sie nichts mehr ausgeben sollen. Du kannst Freunden schreiben, und private Nachrichten sind Ende-zu-Ende-verschlüsselt. Das Board spricht etwa 120 Sprachen, darunter Niederländisch, Flämisch, Piratisch und Klingonisch. Nichts davon kostet einen Cent, und niemand versucht, es dir zu verkaufen.","AI-gile ist ein kleines, persönliches Projekt, kein Unternehmen. Rich wollte mehrere KI-Coding-Projekte betreuen, ohne jede App zu öffnen, um nachzusehen. Also haben er und die Agenten ein Board dafür gebaut und dann mit dem Board den Rest von ihm selbst. Es ist in der geschlossenen Pre-Alpha, das heißt: Es funktioniert, meistens, für eine Handvoll Freunde. Es gibt keine Preisseite, keinen Newsletter und keinen Wachstumsplan. Klingt es nützlich, kannst du fragen, ob du es ausprobieren darfst, sobald es sich etwas weiter öffnet."]},{"n":144,"texts":["AI-gile ist ein Kanban-Board für einen Menschen und viele KI-Agenten. Es läuft auf deinem eigenen Computer und ist völlig kostenlos. Du legst Projekte an, und jedes Projekt bekommt einen Lead und ein kleines Team. Mit dem Lead chattest du, ein bisschen wie bei Discord, und beschreibst eine Idee; der Lead macht daraus Karten und einen Plan und wartet, bis du auf Los drückst. Das Team arbeitet die Karten der Priorität nach ab, mit einer einfachen Kommandozeile, die für Sprachmodelle gemacht ist. Bevor etwas zu dir zurückkommt, folgt ein KI-Tester den Schritten in einer Kopie der App und hängt einen Screenshot an. Fertige Arbeit landet auf deinem Stapel, samt geänderten Dateien und Diff. Du nimmst sie ab, oder du hinterlässt einen Kommentar, und das Team wacht auf und versucht es erneut. Nur du kannst eine Karte nach Erledigt schieben.","Ein Tag mit AI-gile, grob gesagt. Am Abend hinterlässt du ein paar Kommentare: Dieser Knopf sitzt am falschen Platz, jene Liste sollte sortiert sein, könnten wir einen Dunkelmodus haben? Du gehst ins Bett. Die Agenten lesen die Kommentare, ändern, was gewünscht ist, testen es und geben es dir zurück. Läuft Zu tun leer, füllt die Nachtwache es aus dem Backlog mit Karten auf, die keine Antwort von dir brauchen. Am Morgen wartet ein kurzer Stapel: ein paar Fragen und ein paar Dinge zum Ausprobieren, jeweils mit Schritten, denen ein verschlafener Mensch folgen kann, und einem Screenshot, der zeigt, dass es funktioniert. Du klickst dich durch, nimmst die guten ab und schickst den Rest zurück. Ein Token-Zähler zeigt, was das alles gekostet hat, und der Kein-Token-Modus ist für magere Wochen da. Dann frühstückst du, wobei dir die Agenten noch nicht helfen können.","Zuerst, was AI-gile nicht ist. Es ist kein Start-up, es steht nicht zum Verkauf, und niemand sammelt deine Daten. Es ist ein kostenloses Board, das auf deinem Computer läuft, ohne Konten, ohne Tracker und ohne Cookies. Was es ist: ein ordentlicher Ort, um alle KI-Coding-Projekte auf einmal zu sehen, mit einem Team aus Agenten, das die Karten erledigt, und du triffst die Entscheidungen. Es fasst verwandte Karten zusammen, repariert wirre Titel und achtet darauf, wie schlank der Code bleibt. Es spricht etwa 120 Sprachen, von Niederländisch und Flämisch bis Piratisch und Klingonisch. Freunde können sich privat und verschlüsselt schreiben. Gebaut haben es Rich und sehr viele geduldige Agenten, meistens mit sich selbst. Es ist in der geschlossenen Pre-Alpha und deshalb an manchen Stellen rau. Klingt das nach Spaß, frag freundlich, dann kommst du vielleicht früh hinein."]}],"quips":{"1":"Ein Wort. Mutig. Vielleicht zu mutig.","3":"Drei Wörter. Schon ehrlicher als die meisten Produktseiten.","8":"Acht Wörter. Immer noch kürzer als ein Stand-up.","21":"Die Längen sind übrigens Story Points. Natürlich sind sie das.","55":"Fünfundfünfzig Wörter. Zwei Karten wurden fertig, während du das gelesen hast.","144":"Das war die lange Version. Eine 233 gibt es nicht. Die Agenten sind schlafen gegangen."}},"timeline":{"first-idea.name":"Die erste Idee","first-idea.line":"Das allererste Gespräch, noch bevor es Code gab.","first-board.name":"Erstes Board","first-board.line":"Ein Board, das seinen eigenen Bau verfolgt: Karten, Spalten, Drag and Drop, Projekte.","team-roles.name":"Team und Rollen","team-roles.line":"Agentenprofile, Team-Vorlagen, Bereiche und wer was macht.","install.name":"Installation und Releases","install.line":"Ein Zip, das ein Freund installieren kann, mit Selbst-Updates, Kanälen und Rollback.","usage-saver.name":"Verbrauchssparer","usage-saver.line":"Messen, was Läufe kosten, den Code schlank halten, dein Limit schonen.","friends.name":"Freunde und Teilen","friends.line":"Private Nachrichten, ein verschlüsselter Relay, Einladungen, Rollen und geteilte Projekte.","languages.name":"Sprachen","languages.line":"Jeder Bildschirmtext in einer Sprachdatei, zuerst Niederländisch und Flämisch.","ai-tester.name":"KI-Tester","ai-tester.line":"Ein Tester prüft jede Übergabe zuerst und zeigt, was er gesehen hat.","website.name":"Die Website","website.line":"aigile.lol, der Teaser und diese Zeitleiste.","streaming.name":"Chat und Streaming","streaming.line":"Discord, Twitch, OBS, Streamer-Modus, GIFs und Emojis.","no-ai.name":"Edition ohne KI","no-ai.line":"Ein Board für Leute, die ohne KI programmieren, und öffentliche Boards.","night-watch.name":"Nachtwache","night-watch.line":"Ein Wächter und ein Scrum Master halten die Teams bei der Sache, während du schläfst.","p-more.name":"Alles andere","p-more.line":"Kleinere Ideen, die noch auf ihren Auftritt warten.","p-android.name":"Handy und Android","p-android.line":"Dein Board vom Handy aus erreichen, danach eine native Android-App.","p-release.name":"Alpha und weiter","p-release.line":"Geschlossene Alpha, die Live-Seite, dann Beta.","p-languages.name":"Mehr Sprachen","p-languages.line":"Mehr als hundert Sprachen und ein Immersionsmodus für Lernende.","p-engines.name":"Mehr KI-Engines","p-engines.line":"Claude, Codex oder Gemini pro Agent wählen.","p-pro.name":"Profi-Praxis","p-pro.line":"Risiko-Labels, Merge-Gates, Incident-Karten und Leitplanken.","p-self.name":"Auf dich achten","p-self.line":"Müde-Modus, Selbstfürsorge-Erinnerungen und 4:20.","p-servers.name":"Server und Wachstum","p-servers.line":"Globale Servereinstellungen, Rollen und Planung fürs Wachstum.","p-livestream.name":"Streaming-Extras","p-livestream.line":"Twitch-Chat, eigene Emojis und eine öffentliche Live-Ansicht."},"words":{"button":"📖 Entwicklerwörter","h":"📖 Entwicklerwörter erklärt","intro":"Die Wörter, die Entwickler (und die KI-Teams) benutzen, einfach erklärt.","search":"Wort suchen…","none":"Dazu passt kein Wort.","close":"Schließen","list":[{"id":"backlog","word":"Backlog","text":"Ideen und Arbeit, die noch nicht eingeplant sind. Daran wird nichts gearbeitet, bis es nach Zu tun wandert."},{"id":"sprint","word":"Sprint","text":"Ein kurzer Arbeitsabschnitt (oft ein bis zwei Wochen) mit einer vereinbarten Menge an Karten, die fertig werden sollen.","also":["Sprints"]},{"id":"standup","word":"Stand-up","text":"Ein kurzes Abstimmen: was jedes Teammitglied gemacht hat, was es als Nächstes tut und was es aufhält.","also":["Standup","Stand-ups","Daily"]},{"id":"bug","word":"Bug","text":"Etwas, das nicht so funktioniert, wie es soll.","also":["Bugs","Fehler"]},{"id":"test","word":"Test","text":"Ein fertiges Stück Arbeit ausprobieren, um zu prüfen, ob es tut, was verlangt wurde, bevor du es akzeptierst.","also":["Tests"],"noTip":1},{"id":"commit","word":"Commit","text":"Ein gespeicherter Schnappschuss des Codes, mit einer kurzen Notiz, was sich geändert hat. Zu einem kannst du jederzeit zurück.","also":["Commits"]},{"id":"push","word":"Push","text":"Gespeicherte Schnappschüsse (Commits) von diesem Rechner nach GitHub schicken, damit sie gesichert und geteilt sind."},{"id":"branch","word":"Branch","text":"Eine getrennte Arbeitslinie im Code, damit man Änderungen machen kann, ohne die Hauptversion anzufassen.","also":["Branches","Zweig"]},{"id":"merge","word":"Merge","text":"Die Änderungen eines Branches zurück in die Hauptversion zusammenführen."},{"id":"repo","word":"Repo","text":"Der Ordner des Projekts mit Code und der vollständigen Commit-Historie, meist auch auf GitHub gespeichert.","also":["Repository"]},{"id":"refactor","word":"Refactoring","text":"Den Code aufräumen, ohne zu ändern, was er tut: kleinere Dateien, klarere Namen, weniger Wiederholung."},{"id":"deploy","word":"Deploy","text":"Eine neue Version live schalten, zum Beispiel auf einem Server, auf dem Leute sie nutzen."},{"id":"kanban","word":"Kanban","text":"Ein Board mit Spalten (Zu tun, In Arbeit, Erledigt), in dem Karten von links nach rechts wandern, während die Arbeit läuft."},{"id":"wip","word":"WIP-Limit","text":"Work in Progress: die Höchstzahl an Karten in einer Spalte, damit das Team Dinge abschließt, bevor es Neues anfängt.","also":["WIP"]},{"id":"pr","word":"Pull Request","text":"Darum bitten, dass die Änderungen eines Branches geprüft und in die Hauptversion gemergt werden.","also":["PR"]},{"id":"hook","word":"Hook","text":"Ein kleiner Befehl, der zu einem bestimmten Zeitpunkt von selbst läuft, z. B. wenn eine KI-Sitzung startet, damit das Team deine Kommentare mitbekommt.","also":["Hooks"]},{"id":"token","word":"Token","text":"Die Einheit, in der KI-Nutzung gezählt wird: grob ein paar Buchstaben gelesenen oder geschriebenen Texts. Weniger Tokens, mehr bleibt von deinem Tarif.","also":["Tokens"]},{"id":"agent","word":"Agent","text":"Eine KI, die eine Aufgabe selbstständig erledigt: liest den Code, macht Änderungen, führt Prüfungen aus und meldet sich zurück.","also":["Agenten","Agents"]}]}};
